// GENERADO por `npm run construir` a partir de plantillas/*.pdf. No editar.
const decodificar = (b64) => {
  const bin = atob(b64);
  const bytes = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
  return bytes;
};
export const plantillaMenores = () => decodificar('');
export const plantillaAdultos = () => decodificar('');
